-- Read-only evidence collection. Candidate 563fb0e9b79a838a5f394abaffb2f7dc743fc571.
-- Treat output as confidential metadata. Do not publish raw output to GitHub.
\set ON_ERROR_STOP on
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL search_path = pg_catalog, public;
SET LOCAL statement_timeout = '30s';
SET LOCAL lock_timeout = '3s';
SELECT 1 / ((current_database()='beaconhs' AND current_setting('server_version_num')='160015' AND current_setting('transaction_read_only')='on')::integer) AS preflight_guard \gset
SELECT json_build_object('section','identity','database',current_database(),'databaseOid',(SELECT oid::integer FROM pg_database WHERE datname=current_database()),'postgresVersion',current_setting('server_version_num'),'collector',current_user,'readOnly',current_setting('transaction_read_only'),'collectedAt',transaction_timestamp());
SELECT json_build_object('section','ledger','rows',coalesce(json_agg(t ORDER BY t.id),'[]'::json)) FROM (SELECT id,hash,created_at::text FROM drizzle.__drizzle_migrations ORDER BY id) t;
SELECT json_build_object('section',0,'rows',coalesce(json_agg(t),'[]'::json)) FROM (SELECT pg_get_userbyid(datdba) owner,datacl::text acl,datconnlimit,datallowconn FROM pg_database WHERE datname=current_database()) t;
SELECT json_build_object('section',1,'rows',coalesce(json_agg(t),'[]'::json)) FROM (SELECT n.nspname,pg_get_userbyid(n.nspowner) owner,n.nspacl::text acl FROM pg_namespace n WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname <> 'information_schema') t;
SELECT json_build_object('section',2,'rows',coalesce(json_agg(t),'[]'::json)) FROM (SELECT n.nspname,c.relname,c.relkind,c.relrowsecurity,c.relforcerowsecurity,pg_get_userbyid(c.relowner) owner,c.relacl::text acl,c.reloptions,c.relispartition,pg_get_expr(c.relpartbound,c.oid) partition_bound FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname <> 'information_schema') t;
SELECT json_build_object('section',3,'rows',coalesce(json_agg(t),'[]'::json)) FROM (SELECT n.nspname,c.relname,a.attname,a.attnum,format_type(a.atttypid,a.atttypmod) type,a.attnotnull,a.attidentity,a.attgenerated,a.attstorage,a.attcompression,(SELECT collname FROM pg_collation WHERE oid=a.attcollation) collation,a.attacl::text acl,pg_get_expr(d.adbin,d.adrelid) expression FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE a.attnum>0 AND NOT a.attisdropped AND n.nspname NOT LIKE 'pg_%' AND n.nspname <> 'information_schema') t;
SELECT json_build_object('section',4,'rows',coalesce(json_agg(t),'[]'::json)) FROM (SELECT n.nspname,c.relname,k.conname,k.contype,k.convalidated,pg_get_constraintdef(k.oid,true) definition FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname <> 'information_schema') t;
SELECT json_build_object('section',5,'rows',coalesce(json_agg(t),'[]'::json)) FROM (SELECT n.nspname,c.relname,i.indisvalid,i.indisready,pg_get_indexdef(i.indexrelid) definition FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname <> 'information_schema') t;
SELECT json_build_object('section',6,'rows',coalesce(json_agg(t),'[]'::json)) FROM (SELECT n.nspname,c.relname,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid,true) definition FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal AND n.nspname NOT LIKE 'pg_%' AND n.nspname <> 'information_schema') t;
SELECT json_build_object('section',7,'rows',coalesce(json_agg(t),'[]'::json)) FROM (SELECT n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) args,pg_get_functiondef(p.oid) definition,pg_get_userbyid(p.proowner) owner,p.proacl::text acl FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.prokind IN ('f','p') AND n.nspname NOT LIKE 'pg_%' AND n.nspname <> 'information_schema') t;
SELECT json_build_object('section',8,'rows',coalesce(json_agg(t),'[]'::json)) FROM (SELECT schemaname,tablename,policyname,permissive,roles,cmd,qual,with_check FROM pg_policies WHERE schemaname NOT LIKE 'pg_%') t;
SELECT json_build_object('section',9,'rows',coalesce(json_agg(t),'[]'::json)) FROM (SELECT n.nspname,c.relname,pg_get_viewdef(c.oid,true) definition FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN ('v','m') AND n.nspname NOT LIKE 'pg_%' AND n.nspname <> 'information_schema') t;
SELECT json_build_object('section',10,'rows',coalesce(json_agg(t),'[]'::json)) FROM (SELECT n.nspname,t.typname,t.typtype,pg_get_userbyid(t.typowner) owner,t.typacl::text acl,e.enumlabel,e.enumsortorder FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace LEFT JOIN pg_enum e ON e.enumtypid=t.oid WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname <> 'information_schema') t;
SELECT json_build_object('section',11,'rows',coalesce(json_agg(t),'[]'::json)) FROM (SELECT rolname,rolsuper,rolinherit,rolcreaterole,rolcreatedb,rolcanlogin,rolreplication,rolbypassrls,rolconfig FROM pg_roles WHERE rolname LIKE 'beaconhs_%') t;
SELECT json_build_object('section',12,'rows',coalesce(json_agg(t),'[]'::json)) FROM (SELECT p.rolname parent,m.rolname member,a.admin_option,a.inherit_option,a.set_option FROM pg_auth_members a JOIN pg_roles p ON p.oid=a.roleid JOIN pg_roles m ON m.oid=a.member WHERE p.rolname LIKE 'beaconhs_%' OR m.rolname LIKE 'beaconhs_%') t;
SELECT json_build_object('section',13,'rows',coalesce(json_agg(t),'[]'::json)) FROM (SELECT pg_get_userbyid(d.defaclrole) owner,coalesce(n.nspname,'') schema,d.defaclobjtype,d.defaclacl::text acl FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE pg_get_userbyid(d.defaclrole) LIKE 'beaconhs_%') t;
SELECT json_build_object('section',14,'rows',coalesce(json_agg(t),'[]'::json)) FROM (SELECT e.evtname,e.evtevent,e.evtenabled,e.evttags,pg_get_userbyid(e.evtowner) owner,e.evtfoid::regprocedure::text function FROM pg_event_trigger e) t;
SELECT json_build_object('section',15,'rows',coalesce(json_agg(t),'[]'::json)) FROM (SELECT n.nspname,c.relname,r.rulename,pg_get_ruledef(r.oid,true) definition FROM pg_rewrite r JOIN pg_class c ON c.oid=r.ev_class JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname <> 'information_schema') t;
SELECT json_build_object('section',16,'rows',coalesce(json_agg(t),'[]'::json)) FROM (SELECT n.nspname,t.typname,k.conname,pg_get_constraintdef(k.oid,true) definition FROM pg_constraint k JOIN pg_type t ON t.oid=k.contypid JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname <> 'information_schema') t;
SELECT json_build_object('section',17,'rows',coalesce(json_agg(t),'[]'::json)) FROM (SELECT extname,extversion,pg_get_userbyid(extowner) owner FROM pg_extension) t;
SELECT json_build_object('section',18,'rows',coalesce(json_agg(t),'[]'::json)) FROM (SELECT schemaname,sequencename,sequenceowner,data_type,start_value,min_value,max_value,increment_by,cycle,cache_size FROM pg_sequences WHERE schemaname NOT LIKE 'pg_%') t;
ROLLBACK;
